680	func updateDecentralizedMigrationCondition(vmi *virtv1.VirtualMachineInstance, migrationCopy *virtv1.VirtualMachineInstanceMigration, conditionManager *controller.VirtualMachineInstanceMigrationConditionManager) error {
681		if vmiCondition := controller.NewVirtualMachineInstanceConditionManager().GetCondition(vmi, virtv1.VirtualMachineInstanceDecentralizedLiveMigrationFailure); vmiCondition != nil {
682			condition := virtv1.VirtualMachineInstanceMigrationCondition{
683				Type:          virtv1.VirtualMachineInstanceDecentralizedMigrationBlocked,
684				Reason:        vmiCondition.Reason,
685				Message:       vmiCondition.Message,
686				Status:        k8sv1.ConditionTrue,
687				LastProbeTime: v1.Now(),
688			}
689			if !conditionManager.HasCondition(migrationCopy, virtv1.VirtualMachineInstanceDecentralizedMigrationBlocked) {
690				migrationCopy.Status.Conditions = append(migrationCopy.Status.Conditions, condition)
691			} else {
692				conditionManager.UpdateCondition(migrationCopy, &condition)
693			}
694		} else {
695			conditionManager.RemoveCondition(migrationCopy, virtv1.VirtualMachineInstanceDecentralizedMigrationBlocked)
696		}
697		return nil
698	}
