//
//   - When newMS is nil, a "test" followed by a "remove" operation is generated
//     for the whole /status/migrationState object.
//   - For each field that changed from its zero value to a non-zero value, an
//     "add" operation is generated at /status/migrationState/<jsonFieldName>.
//   - For each field that is non-zero in both objects but differs, a "test"
//     followed by a "replace" operation is generated.
//   - Fields whose values are identical are skipped.
func addMigrationStateFieldPatches(patchSet *patch.PatchSet, origMS, newMS *virtv1.VirtualMachineInstanceMigrationState) {
	if newMS == nil {
		patchSet.AddOption(
			patch.WithTest("/status/migrationState", origMS),
			patch.WithRemove("/status/migrationState"),
		)
		return
	}

	if origMS == nil {
		origMS = &virtv1.VirtualMachineInstanceMigrationState{}
	}

	origVal := reflect.ValueOf(*origMS)
	newVal := reflect.ValueOf(*newMS)
	stateType := origVal.Type()

