			patchSet.AddOption(patch.WithAdd(path, newField.Interface()))
		case !origField.IsZero() && !newField.IsZero():
			patchSet.AddOption(
				patch.WithTest(path, origField.Interface()),
				patch.WithReplace(path, newField.Interface()),
			)
		}
	}
}

