[metadata] {"filePath": "/workspace/repo/pkg/virt-handler/migration-target.go", "oldString": "func migrationNeedsFinalization(migrationState *v1.VirtualMachineInstanceMigrationState) bool {", "newString": "// migrationProxyKey returns the key to use when looking up the migration proxy
// for a given VMI. For regular migrations this is the local VMI UID. For
// decentralized UNIX transport migrations (the VMI has the CreateMigrationTarget
// annotation, MigrationTransport is MigrationTransportUnix and the source VMI UID
// is known), the source VMI UID is used instead so that both sides of the
// migration agree on the proxy key.
func migrationProxyKey(vmi *v1.VirtualMachineInstance) string {
	if vmi.IsMigrationTarget() &&
		vmi.Status.MigrationTransport == v1.MigrationTransportUnix &&
		vmi.Status.MigrationState != nil &&
		vmi.Status.MigrationState.SourceState != nil &&
		vmi.Status.MigrationState.SourceState.VirtualMachineInstanceUID != nil {
		return string(*vmi.Status.MigrationState.SourceState.VirtualMachineInstanceUID)
	}
	return string(vmi.UID)
}

